-- =========================================================
-- SYSTEM: Light Ticket Management (LTM)
-- SCRIPT: ALL-IN-ONE (schema + dữ liệu mẫu + dữ liệu demo đặt vé)
--
-- !!! CẢNH BÁO: script DROP rồi tạo lại database LightTicketDB. CHỈ dùng cho lần cài mới / môi trường dev.
--     Database đang chạy thật: áp dụng từng file trong db/migrations (001..00x), KHÔNG chạy file này.
--
-- Đã gộp:  migrations 002-006  +  seed_demo_events.sql  +  seat map / organizer profile.
-- (001 chỉ sửa dữ liệu cũ viết hoa role; DB mới đã insert đúng dạng nên không cần.)
--
-- Chạy:  sqlcmd -S localhost -U sa -P <pwd> -C -f 65001 -i db.sql
--        (file UTF-8 có BOM; -f 65001 để tiếng Việt không vỡ)
--
-- Bố cục:  PHẦN 1 schema | PHẦN 2 dữ liệu mẫu cơ bản | PHẦN 3 organizer profile
--          PHẦN 4 sơ đồ ghế sự kiện 1 | PHẦN 4b mật khẩu test (Test@123) | PHẦN 5 demo đặt vé (có thể xóa)
--          PHẦN 6 dữ liệu test mở rộng: 40 sự kiện + đơn hàng, vé, check-in, review (có thể xóa)
-- Sau khi chạy xong đăng nhập được ngay bằng Test@123, không cần chạy thêm lệnh nào.
-- =========================================================

-- Bắt buộc cho filtered index (UX_Organizer_Profiles_tax_code). SSMS bật sẵn,
-- nhưng sqlcmd / một số công cụ khác mặc định tắt QUOTED_IDENTIFIER.
SET ANSI_NULLS ON;
SET QUOTED_IDENTIFIER ON;
GO

USE master;
GO

-- Xóa database cũ nếu đã tồn tại
IF DB_ID('LightTicketDB') IS NOT NULL
BEGIN
    ALTER DATABASE LightTicketDB SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
    DROP DATABASE LightTicketDB;
END
GO

-- Tạo database mới
CREATE DATABASE LightTicketDB;
GO

-- Sử dụng database mới
USE LightTicketDB;
GO

-- =========================================================
-- PHẦN 1. SCHEMA (16 bảng; Event_Tickets/Event_Zones tạo trước Event_Seats vì Event_Seats tham chiếu Event_Zones)
-- =========================================================
-- 1. USERS TABLE
CREATE TABLE Users (
    user_id INT IDENTITY(1,1) PRIMARY KEY,
    username VARCHAR(50) NOT NULL UNIQUE,
    email VARCHAR(255) NOT NULL UNIQUE,
    password VARCHAR(255) NOT NULL,
    full_name NVARCHAR(100) NOT NULL,
    phone VARCHAR(20),
    address NVARCHAR(255),
    role VARCHAR(20) NOT NULL, -- Customer, Staff, Organizer, Admin
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    failed_attempts INT DEFAULT 0,
    locked_until DATETIME2,
    must_change_password BIT NOT NULL DEFAULT 0, -- tài khoản Admin tạo với mật khẩu tạm
    password_set BIT NOT NULL DEFAULT 1, -- 0: tài khoản Google chưa tự đặt mật khẩu (Thiết lập mật khẩu không hỏi mật khẩu cũ)
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE()
);

-- 2. CATEGORIES TABLE
CREATE TABLE Categories (
    category_id INT IDENTITY(1,1) PRIMARY KEY,
    category_name NVARCHAR(100) NOT NULL,
    description NVARCHAR(500),
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    failed_attempts INT DEFAULT 0,
    locked_until DATETIME2,
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE()
);

-- 3. VENUES TABLE
CREATE TABLE Venues (
    venue_id INT IDENTITY(1,1) PRIMARY KEY,
    venue_name NVARCHAR(200) NOT NULL,
    address NVARCHAR(500) NOT NULL,
    description NVARCHAR(1000),
    capacity INT NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    failed_attempts INT DEFAULT 0,
    locked_until DATETIME2,
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE()
);

-- 4. SEAT MAPS TABLE
CREATE TABLE Seat_Maps (
    seat_map_id INT IDENTITY(1,1) PRIMARY KEY,
    venue_id INT NOT NULL FOREIGN KEY REFERENCES Venues(venue_id),
    map_name NVARCHAR(150) NOT NULL,
    description NVARCHAR(500),
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    failed_attempts INT DEFAULT 0,
    locked_until DATETIME2,
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE()
);

-- 5. SEATS TABLE
CREATE TABLE Seats (
    seat_id INT IDENTITY(1,1) PRIMARY KEY,
    seat_map_id INT NOT NULL FOREIGN KEY REFERENCES Seat_Maps(seat_map_id),
    row_label VARCHAR(20) NOT NULL,
    seat_number INT NOT NULL,
    seat_label VARCHAR(50) NOT NULL,
    seat_type VARCHAR(30) NOT NULL, -- VIP, Standard
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE'
);

-- 6. EVENTS TABLE
CREATE TABLE Events (
    event_id INT IDENTITY(1,1) PRIMARY KEY,
    organizer_id INT NOT NULL FOREIGN KEY REFERENCES Users(user_id),
    category_id INT NOT NULL FOREIGN KEY REFERENCES Categories(category_id),
    venue_id INT NOT NULL FOREIGN KEY REFERENCES Venues(venue_id),
    event_name NVARCHAR(200) NOT NULL,
    description NVARCHAR(MAX),
    event_image VARCHAR(500),
    start_time DATETIME2 NOT NULL,
    end_time DATETIME2 NOT NULL,
    status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE',
    cancellation_reason NVARCHAR(1000),
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE()
);

-- 8. EVENT TICKETS TABLE
CREATE TABLE Event_Tickets (
    event_ticket_id INT IDENTITY(1,1) PRIMARY KEY,
    event_id INT NOT NULL FOREIGN KEY REFERENCES Events(event_id),
    ticket_name NVARCHAR(100) NOT NULL,
    description NVARCHAR(500),
    price DECIMAL(18,2) NOT NULL,
    quantity INT NOT NULL,
    available_quantity INT NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    failed_attempts INT DEFAULT 0,
    locked_until DATETIME2,
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE()
);

-- 8b. EVENT ZONES TABLE: khu vực của sơ đồ (sân khấu / khu ngồi hàng x ghế / khu đứng)
CREATE TABLE Event_Zones (
    zone_id INT IDENTITY(1,1) PRIMARY KEY,
    event_id INT NOT NULL FOREIGN KEY REFERENCES Events(event_id),
    event_ticket_id INT NULL FOREIGN KEY REFERENCES Event_Tickets(event_ticket_id), -- hạng vé (giá) của khu; NULL với sân khấu
    zone_name NVARCHAR(100) NOT NULL,
    zone_type VARCHAR(20) NOT NULL,            -- SEATED, STANDING, STAGE
    color VARCHAR(7) NOT NULL DEFAULT '#FF7043',
    pos_x INT NOT NULL,
    pos_y INT NOT NULL,
    width INT NOT NULL,
    height INT NOT NULL,
    row_count INT NOT NULL DEFAULT 0,          -- chỉ khu ngồi
    seats_per_row INT NOT NULL DEFAULT 0,      -- chỉ khu ngồi
    capacity INT NOT NULL DEFAULT 0,           -- số chỗ bán được (khu ngồi = số ghế thực tế)
    blocked_seats NVARCHAR(MAX) NULL,          -- ghế bỏ trống/lối đi, dạng "r:c,r:c" (chỉ số từ 0)
    sort_order INT NOT NULL DEFAULT 0,
    CONSTRAINT UQ_Event_Zones_Name UNIQUE (event_id, zone_name)
);

-- 7. EVENT SEATS TABLE
CREATE TABLE Event_Seats (
    event_seat_id INT IDENTITY(1,1) PRIMARY KEY,
    event_id INT NOT NULL FOREIGN KEY REFERENCES Events(event_id),
    source_seat_id INT NULL FOREIGN KEY REFERENCES Seats(seat_id), -- NULL: ghế Organizer tự vẽ, không có ghế gốc theo địa điểm
    zone_id INT NULL FOREIGN KEY REFERENCES Event_Zones(zone_id),
    row_label VARCHAR(20) NOT NULL,
    seat_number INT NOT NULL,
    seat_label VARCHAR(50) NOT NULL,
    seat_type VARCHAR(30) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'Available' -- Available, Held, Sold
);

-- 9. EVENT STAFF TABLE
CREATE TABLE Event_Staff (
    event_staff_id INT IDENTITY(1,1) PRIMARY KEY,
    event_id INT NOT NULL FOREIGN KEY REFERENCES Events(event_id),
    staff_id INT NOT NULL FOREIGN KEY REFERENCES Users(user_id),
    assigned_at DATETIME2 DEFAULT GETDATE(),
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE'
);

-- 10. VOUCHERS TABLE
CREATE TABLE Vouchers (
    voucher_id INT IDENTITY(1,1) PRIMARY KEY,
    voucher_code VARCHAR(50) NOT NULL UNIQUE,
    voucher_name NVARCHAR(150) NOT NULL,
    discount_type VARCHAR(20) NOT NULL, -- Percentage, Fixed
    discount_value DECIMAL(18,2) NOT NULL,
    min_order_amount DECIMAL(18,2) DEFAULT 0,
    max_discount_amount DECIMAL(18,2),
    start_time DATETIME2 NOT NULL,
    end_time DATETIME2 NOT NULL,
    usage_limit INT NOT NULL,
    used_count INT DEFAULT 0,
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE',
    failed_attempts INT DEFAULT 0,
    locked_until DATETIME2,
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE()
);

-- 11. ORDERS TABLE
CREATE TABLE Orders (
    order_id INT IDENTITY(1,1) PRIMARY KEY,
    customer_id INT NOT NULL FOREIGN KEY REFERENCES Users(user_id),
    voucher_id INT NULL FOREIGN KEY REFERENCES Vouchers(voucher_id),
    order_code VARCHAR(50) NOT NULL UNIQUE,
    total_amount DECIMAL(18,2) NOT NULL,
    discount_amount DECIMAL(18,2) DEFAULT 0,
    final_amount DECIMAL(18,2) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'Pending', -- Pending, Paid, Cancelled
    hold_started_at DATETIME2,
    hold_expired_at DATETIME2,
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE()
);

-- 12. ORDER DETAILS TABLE
CREATE TABLE Order_Details (
    order_detail_id INT IDENTITY(1,1) PRIMARY KEY,
    order_id INT NOT NULL FOREIGN KEY REFERENCES Orders(order_id),
    event_ticket_id INT NOT NULL FOREIGN KEY REFERENCES Event_Tickets(event_ticket_id),
    quantity INT NOT NULL,
    unit_price DECIMAL(18,2) NOT NULL,
    subtotal DECIMAL(18,2) NOT NULL
);

-- 13. ORDER SEATS TABLE
CREATE TABLE Order_Seats (
    order_seat_id INT IDENTITY(1,1) PRIMARY KEY,
    order_id INT NOT NULL FOREIGN KEY REFERENCES Orders(order_id),
    event_seat_id INT NOT NULL FOREIGN KEY REFERENCES Event_Seats(event_seat_id),
    created_at DATETIME2 DEFAULT GETDATE()
);

-- 14. PAYMENTS TABLE
CREATE TABLE Payments (
    payment_id INT IDENTITY(1,1) PRIMARY KEY,
    order_id INT NOT NULL FOREIGN KEY REFERENCES Orders(order_id),
    payment_method VARCHAR(30) NOT NULL, -- VNPAY
    transaction_code VARCHAR(100),
    amount DECIMAL(18,2) NOT NULL,
    payment_status VARCHAR(20) NOT NULL DEFAULT 'Success',
    paid_at DATETIME2,
    created_at DATETIME2 DEFAULT GETDATE()
);

-- 15. TICKETS TABLE
CREATE TABLE Tickets (
    ticket_id INT IDENTITY(1,1) PRIMARY KEY,
    order_detail_id INT NOT NULL FOREIGN KEY REFERENCES Order_Details(order_detail_id),
    event_id INT NOT NULL FOREIGN KEY REFERENCES Events(event_id),
    event_seat_id INT NULL FOREIGN KEY REFERENCES Event_Seats(event_seat_id),
    ticket_code VARCHAR(100) NOT NULL UNIQUE,
    qr_code VARCHAR(500) NOT NULL,
    ticket_status VARCHAR(30) NOT NULL DEFAULT 'Valid', -- Valid, CheckedIn, Cancelled
    check_in_time DATETIME2 NULL,
    created_at DATETIME2 DEFAULT GETDATE(),
    CONSTRAINT UQ_Tickets_id_event UNIQUE (ticket_id, event_id), -- để Reviews tham chiếu cặp (vé, sự kiện)
    CONSTRAINT CK_Tickets_checkin CHECK (  -- chỉ vé CheckedIn mới có giờ check-in
        (ticket_status = 'CheckedIn' AND check_in_time IS NOT NULL)
        OR (ticket_status <> 'CheckedIn' AND check_in_time IS NULL))
);

-- 16. REVIEWS TABLE
CREATE TABLE Reviews (
    review_id INT IDENTITY(1,1) PRIMARY KEY,
    customer_id INT NOT NULL FOREIGN KEY REFERENCES Users(user_id),
    event_id INT NOT NULL FOREIGN KEY REFERENCES Events(event_id),
    ticket_id INT NOT NULL FOREIGN KEY REFERENCES Tickets(ticket_id),
    rating INT NOT NULL CHECK (rating BETWEEN 1 AND 5),
    comment NVARCHAR(1000),
    status VARCHAR(20) NOT NULL DEFAULT 'ACTIVE' CONSTRAINT CK_Reviews_status CHECK (status IN ('ACTIVE', 'HIDDEN')), -- HIDDEN: Admin ẩn
    failed_attempts INT DEFAULT 0,
    locked_until DATETIME2,
    created_at DATETIME2 DEFAULT GETDATE(),
    updated_at DATETIME2 DEFAULT GETDATE(),
    CONSTRAINT UX_Reviews_customer_event UNIQUE (customer_id, event_id), -- 1 đánh giá / khách / sự kiện
    CONSTRAINT FK_Reviews_ticket_event FOREIGN KEY (ticket_id, event_id)   -- vé phải thuộc đúng sự kiện được đánh giá
        REFERENCES Tickets(ticket_id, event_id)
);
GO

-- Một ghế chỉ có tối đa một vé hiệu lực (vé Cancelled không tính nên ghế bán lại được) - trước là migration 006
CREATE UNIQUE NONCLUSTERED INDEX UX_Tickets_ActiveSeat
    ON Tickets (event_seat_id)
    WHERE event_seat_id IS NOT NULL AND ticket_status IN ('Valid', 'CheckedIn');
GO

