-- ---------------------------------------------------------------- 6.4 Sự kiện, hạng vé, sơ đồ khu, ghế
DECLARE @now DATETIME2(0) = DATEADD(HOUR, DATEDIFF(HOUR, 0, GETDATE()), 0);   -- mốc "bây giờ" (làm tròn giờ); mọi thời điểm bên dưới tính tương đối so với mốc này
CREATE TABLE #N (n INT PRIMARY KEY);
INSERT INTO #N SELECT TOP 64 ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1 FROM sys.all_objects;
CREATE TABLE #EV (k INT PRIMARY KEY, event_name NVARCHAR(200), cat NVARCHAR(100), venue NVARCHAR(200), org VARCHAR(50), descr NVARCHAR(MAX), start_off INT, end_off INT, status VARCHAR(30), reason NVARCHAR(1000), created_off INT);
