(5, N'Workshop Làm Gốm Đồng Nai Cho Người Mới', N'Hội thảo & Workshop', N'Nhà Văn hóa Thanh Niên', 'organizer01', N'Buổi học làm gốm cơ bản: nhào đất, vuốt bát và trang trí. Mỗi học viên mang về một sản phẩm tự tay làm. Lớp giới hạn 40 chỗ.', -48840, -48660, 'ACTIVE', NULL, -113718),
(6, N'Triển Lãm Ánh Sáng: Sài Gòn Về Đêm', N'Triển lãm & Nghệ thuật', N'Trung tâm Hội chợ Triển lãm Sài Gòn (SECC)', 'organizer02', N'Triển lãm nghệ thuật ánh sáng tương tác, tái hiện Sài Gòn về đêm qua các tác phẩm trình chiếu, gương và âm thanh.', -129780, -107460, 'ACTIVE', NULL, -198331),
(7, N'Kịch Nói: Mùa Nước Nổi', N'Sân Khấu & Kịch', N'Cung Văn hóa Hữu nghị Việt Xô', 'organizer03', N'Vở kịch nói về một gia đình miền Tây qua mùa nước lên, với dàn diễn viên sân khấu Hà Nội. Ghế ngồi đánh số chia hai hạng.', -98910, -98775, 'ACTIVE', NULL, -164248),
(8, N'Liveshow Thu Hà: Phố Cổ Chiều Tà', N'Concert Âm Nhạc', N'Nhà Hát Lớn Hà Nội', 'organizer03', N'Liveshow những bản tình ca về Hà Nội trong không gian cổ điển của Nhà Hát Lớn. Số lượng ghế giới hạn.', -18240, -18090, 'ACTIVE', NULL, -87261),
(9, N'Hội Thảo Khởi Nghiệp & Đầu Tư 2026', N'Hội thảo & Workshop', N'Trung tâm Hội nghị Quốc gia', 'organizer03', N'Một ngày với các nhà sáng lập và nhà đầu tư: huy động vốn, xây dựng đội ngũ và mở rộng thị trường. Có phiên kết nối trực tiếp.', -8880, -8340, 'ACTIVE', NULL, -74765),
(10, N'Đại Nhạc Hội Mùa Hè Đà Lạt', N'Concert Âm Nhạc', N'Quảng trường Lâm Viên', 'organizer01', N'Đại nhạc hội ngoài trời cạnh hồ Xuân Hương với nhiều nghệ sĩ khách mời. Khu đứng tự do trước sân khấu và khán đài ngồi phía sau.', -119160, -118860, 'ACTIVE', NULL, -184738),
(11, N'Giải Bóng Rổ Học Đường Toàn Quốc: Vòng Chung Kết', N'Thể thao', N'Nhà thi đấu Phú Thọ', 'organizer02', N'Trận chung kết và tranh hạng ba giải bóng rổ học đường toàn quốc, thi đấu trong nhà tại Phú Thọ.', -17160, -16800, 'ACTIVE', NULL, -82356),
(12, N'Nhạc Kịch Thiếu Nhi: Cuộc Phiêu Lưu Của Mèo Con', N'Gia đình & Thiếu nhi', N'Nhà hát Hòa Bình', 'organizer02', N'Nhạc kịch cho trẻ từ 4 tuổi với hóa trang, múa và ca hát. Trẻ dưới 3 tuổi không cần vé nhưng ngồi cùng phụ huynh.', -37590, -37470, 'ACTIVE', NULL, -105596),
(13, N'Festival Cuối Tuần: Nhạc Sống & Phim Ngắn', N'Concert Âm Nhạc', N'Nhà Văn hóa Thanh Niên', 'organizer01', N'Sự kiện cả ngày kết hợp biểu diễn nhạc sống và chiếu phim ngắn của các nhà làm phim trẻ. Khu đứng tự do và khu ngồi đánh số.', -60, 180, 'ACTIVE', NULL, -65286),
(14, N'Countdown 2027: Đại Tiệc Âm Nhạc Sài Gòn', N'Concert Âm Nhạc', N'Nhà thi đấu Phú Thọ', 'organizer02', N'Đại tiệc âm nhạc đón năm mới với dàn nghệ sĩ hàng đầu, pháo hoa trong nhà và đếm ngược cùng khán giả.', 69540, 69900, 'ACTIVE', NULL, -15298),
(15, N'Hòa Nhạc Giao Hưởng Mùa Đông', N'Concert Âm Nhạc', N'Nhà Hát Lớn Hà Nội', 'organizer03', N'Dàn nhạc giao hưởng trình diễn các tác phẩm kinh điển của Tchaikovsky và Dvořák trong không gian Nhà Hát Lớn.', 50880, 51000, 'ACTIVE', NULL, -16897),
(16, N'Kịch Nói: Gia Đình Nhà Họ Phan', N'Sân Khấu & Kịch', N'Nhà hát Hòa Bình', 'organizer02', N'Vở kịch tâm lý gia đình ba thế hệ xoay quanh một căn nhà cũ ở Sài Gòn. Ghế ngồi đánh số.', 22050, 22200, 'ACTIVE', NULL, -43004),
(17, N'Stand-up Comedy Night: Chuyện Nhỏ Thành Phố', N'Hài kịch & Stand-up', N'Nhà Văn hóa Thanh Niên', 'organizer01', N'Đêm hài độc thoại về cuộc sống thành phố: kẹt xe, giá nhà và hẹn hò. Hạng Vàng đã bán hết.', 12000, 12120, 'ACTIVE', NULL, -55253),
(18, N'Triển Lãm Nghệ Thuật Đương Đại: Dòng Chảy', N'Triển lãm & Nghệ thuật', N'Trung tâm Hội chợ Triển lãm Sài Gòn (SECC)', 'organizer03', N'Triển lãm kéo dài một tháng với hơn 60 tác phẩm sắp đặt, hội họa và video art của nghệ sĩ trong nước và quốc tế.', 9960, 53760, 'ACTIVE', NULL, -58933),
