(21, N'Giải Futsal Doanh Nghiệp Mekong Cup', N'Thể thao', N'Sân vận động Cần Thơ', 'organizer02', N'Vòng chung kết giải futsal giữa các doanh nghiệp khu vực Đồng bằng sông Cửu Long, thi đấu buổi chiều và tối.', 41940, 42300, 'ACTIVE', NULL, -26991),
