(23, N'Nhạc Hội EDM: Neon Nights', N'Concert Âm Nhạc', N'Nhà thi đấu Phú Thọ', 'organizer02', N'Đêm nhạc điện tử với DJ trong nước và quốc tế, hệ thống âm thanh ánh sáng quy mô lớn. Dành cho khán giả từ 18 tuổi.', 92580, 92850, 'ACTIVE', NULL, -16543),
