INSERT INTO Events (organizer_id, category_id, venue_id, event_name, description, event_image, start_time, end_time, status, cancellation_reason, created_at, updated_at)
SELECT u.user_id, c.category_id, ve.venue_id, e.event_name, e.descr, NULL, DATEADD(MINUTE, e.start_off, @now), DATEADD(MINUTE, e.end_off, @now),
       e.status, e.reason, DATEADD(MINUTE, e.created_off, @now), DATEADD(MINUTE, e.created_off, @now)
FROM #EV e
JOIN Users u ON u.username = e.org
JOIN Categories c ON c.category_name = e.cat
JOIN Venues ve ON ve.venue_name = e.venue
ORDER BY e.k;

CREATE TABLE #EVID (k INT PRIMARY KEY, event_id INT NOT NULL);
INSERT INTO #EVID SELECT e.k, ev.event_id FROM #EV e JOIN Events ev ON ev.event_name = e.event_name;

CREATE TABLE #TK (k INT, tidx INT, ticket_name NVARCHAR(100), descr NVARCHAR(500), price DECIMAL(18,2), seated BIT, PRIMARY KEY (k, tidx));
