INSERT INTO Event_Tickets (event_id, ticket_name, description, price, quantity, available_quantity, status, created_at, updated_at)
SELECT i.event_id, t.ticket_name, t.descr, t.price, cap.qty, cap.qty, 'ACTIVE', DATEADD(MINUTE, e.created_off, @now), DATEADD(MINUTE, e.created_off, @now)
FROM #TK t
JOIN #EV e ON e.k = t.k
JOIN #EVID i ON i.k = t.k
CROSS APPLY (SELECT SUM(z.cap) AS qty FROM #ZN z WHERE z.k = t.k AND z.tidx = t.tidx) cap
ORDER BY t.k, t.tidx;

CREATE TABLE #TKID (k INT, tidx INT, event_ticket_id INT NOT NULL, PRIMARY KEY (k, tidx));
INSERT INTO #TKID
SELECT t.k, t.tidx, et.event_ticket_id FROM #TK t JOIN #EVID i ON i.k = t.k
JOIN Event_Tickets et ON et.event_id = i.event_id AND et.ticket_name = t.ticket_name;

INSERT INTO Event_Zones (event_id, event_ticket_id, zone_name, zone_type, color, pos_x, pos_y, width, height, row_count, seats_per_row, capacity, blocked_seats, sort_order)
SELECT i.event_id, ti.event_ticket_id, z.zname, z.ztype, z.color, z.x, z.y, z.w, z.h, z.rows_, z.cols_, z.cap, z.blocked, z.sort_
FROM #ZN z
JOIN #EVID i ON i.k = z.k
LEFT JOIN #TKID ti ON ti.k = z.k AND ti.tidx = z.tidx
ORDER BY z.k, z.sort_;

-- Ghế cho khu ngồi (giống trình thiết kế sơ đồ: row_label = {mã khu}-{chữ hàng}, bỏ các vị trí lối đi trong blocked_seats)
INSERT INTO Event_Seats (event_id, source_seat_id, zone_id, row_label, seat_number, seat_label, seat_type, status)
SELECT i.event_id, NULL, ez.zone_id, z.code + '-' + CHAR(65 + r.n), c.n + 1,
       z.code + '-' + CHAR(65 + r.n) + RIGHT('0' + CAST(c.n + 1 AS VARCHAR(2)), 2),
       CASE WHEN LOWER(z.zname) LIKE '%vip%' THEN 'VIP' ELSE 'Standard' END, 'Available'
FROM #ZN z
JOIN #EVID i ON i.k = z.k
JOIN Event_Zones ez ON ez.event_id = i.event_id AND ez.zone_name = z.zname
JOIN #N r ON r.n < z.rows_
JOIN #N c ON c.n < z.cols_
WHERE z.ztype = 'SEATED'
  AND (z.blocked IS NULL OR CHARINDEX(',' + CAST(r.n AS VARCHAR(3)) + ':' + CAST(c.n AS VARCHAR(3)) + ',', ',' + z.blocked + ',') = 0)
ORDER BY z.k, z.sort_, r.n, c.n;

