INSERT INTO Event_Staff (event_id, staff_id, status, assigned_at)
SELECT i.event_id, u.user_id, 'ACTIVE', DATEADD(MINUTE, e.created_off + 1440, @now)
FROM #ES s JOIN #EVID i ON i.k = s.k JOIN #EV e ON e.k = s.k JOIN Users u ON u.username = s.staff;
