-- ---------------------------------------------------------------- 6.5 Đơn hàng, thanh toán, vé, check-in
DECLARE @now DATETIME2(0) = DATEADD(HOUR, DATEDIFF(HOUR, 0, GETDATE()), 0);   -- mốc "bây giờ" (làm tròn giờ); mọi thời điểm bên dưới tính tương đối so với mốc này
CREATE TABLE #ORD (code VARCHAR(30) PRIMARY KEY, cust INT, k INT, voucher VARCHAR(50) NULL, st VARCHAR(20), c_off INT, disc DECIMAL(18,2), chk INT NULL, t1 INT NULL, q1 INT NULL, t2 INT NULL, q2 INT NULL);
