-- Đơn hàng: tổng tiền = tổng (số lượng x đơn giá hạng vé); giảm giá đã tính theo quy tắc voucher của hệ thống
INSERT INTO Orders (customer_id, voucher_id, order_code, total_amount, discount_amount, final_amount, status, hold_started_at, hold_expired_at, created_at, updated_at)
SELECT u.user_id, vc.voucher_id, d.code, tot.total, d.disc, tot.total - d.disc, d.st,
       DATEADD(MINUTE, d.c_off, @now), DATEADD(MINUTE, d.c_off + 10, @now), DATEADD(MINUTE, d.c_off, @now),
       DATEADD(MINUTE, d.c_off + CASE d.st WHEN 'Paid' THEN 4 WHEN 'Cancelled' THEN 11 ELSE 0 END, @now)
FROM #ORD d
JOIN Users u ON u.username = 'customer' + RIGHT('0' + CAST(d.cust AS VARCHAR(2)), 2)
LEFT JOIN Vouchers vc ON vc.voucher_code = d.voucher
CROSS APPLY (SELECT SUM(x.q * tk.price) AS total
             FROM (VALUES (d.t1, d.q1), (d.t2, d.q2)) AS x(t, q)
             JOIN #TK tk ON tk.k = d.k AND tk.tidx = x.t
             WHERE x.t IS NOT NULL) tot
ORDER BY d.c_off, d.code;

INSERT INTO Order_Details (order_id, event_ticket_id, quantity, unit_price, subtotal)
SELECT o.order_id, ti.event_ticket_id, x.q, tk.price, x.q * tk.price
FROM #ORD d
JOIN Orders o ON o.order_code = d.code
CROSS APPLY (VALUES (d.t1, d.q1), (d.t2, d.q2)) AS x(t, q)
JOIN #TK tk ON tk.k = d.k AND tk.tidx = x.t
JOIN #TKID ti ON ti.k = d.k AND ti.tidx = x.t
WHERE x.t IS NOT NULL
ORDER BY o.order_id, x.t;

-- Ghế của đơn (đơn Cancelled vẫn giữ lịch sử ghế như hệ thống thật)
INSERT INTO Order_Seats (order_id, event_seat_id, created_at)
SELECT o.order_id, es.event_seat_id, o.created_at
FROM #OSR s
JOIN #ORD d ON d.code = s.code
JOIN Orders o ON o.order_code = s.code
JOIN #EVID i ON i.k = d.k
JOIN Event_Seats es ON es.event_id = i.event_id AND es.row_label = s.row_label
                   AND es.seat_number BETWEEN s.from_no AND s.from_no + s.cnt - 1
ORDER BY o.order_id, es.event_seat_id;

INSERT INTO Payments (order_id, payment_method, transaction_code, amount, payment_status, paid_at, created_at)
SELECT o.order_id, 'VNPAY',
       CASE WHEN d.st = 'Pending' THEN NULL
            ELSE 'VNP' + RIGHT('00000000' + CAST(ABS(CAST(CHECKSUM(d.code) AS BIGINT)) % 100000000 AS VARCHAR(8)), 8) END,
       o.final_amount,
       CASE d.st WHEN 'Paid' THEN 'Success' WHEN 'Pending' THEN 'Pending'
                 ELSE CASE WHEN rf.code IS NOT NULL THEN 'RefundPending' ELSE 'Failed' END END,
       CASE WHEN rf.code IS NOT NULL THEN DATEADD(MINUTE, 14, o.created_at)   -- thanh toán đến sau khi đã hết giữ chỗ / sự kiện hủy
            WHEN d.st = 'Paid' THEN DATEADD(MINUTE, 4, o.created_at) END,
       o.created_at
FROM #ORD d
JOIN Orders o ON o.order_code = d.code
LEFT JOIN #RF rf ON rf.code = d.code
ORDER BY o.order_id;

-- Vé khu đứng (không gắn ghế)
INSERT INTO Tickets (order_detail_id, event_id, event_seat_id, ticket_code, qr_code, ticket_status, check_in_time, created_at)
SELECT od.order_detail_id, i.event_id, NULL, c.code, c.code,
       CASE WHEN d.chk IS NULL THEN 'Valid' ELSE 'CheckedIn' END,
       CASE WHEN d.chk IS NULL THEN NULL ELSE DATEADD(MINUTE, d.chk + (n.n % 4), @now) END,
       DATEADD(MINUTE, d.c_off + 4, @now)
FROM #ORD d
JOIN Orders o ON o.order_code = d.code
JOIN #EVID i ON i.k = d.k
CROSS APPLY (VALUES (d.t1, d.q1), (d.t2, d.q2)) AS x(t, q)
JOIN #TK tk ON tk.k = d.k AND tk.tidx = x.t AND tk.seated = 0
JOIN #TKID ti ON ti.k = d.k AND ti.tidx = x.t
JOIN Order_Details od ON od.order_id = o.order_id AND od.event_ticket_id = ti.event_ticket_id
JOIN #N n ON n.n < x.q
CROSS APPLY (SELECT 'TKT-' + CONVERT(VARCHAR(32), HASHBYTES('MD5', d.code + ':' + CAST(x.t AS VARCHAR(3)) + ':' + CAST(n.n AS VARCHAR(3))), 2) AS code) c
WHERE d.st = 'Paid' AND x.t IS NOT NULL
ORDER BY o.order_id, n.n;

-- Vé khu ngồi (mỗi ghế một vé)
INSERT INTO Tickets (order_detail_id, event_id, event_seat_id, ticket_code, qr_code, ticket_status, check_in_time, created_at)
SELECT od.order_detail_id, i.event_id, es.event_seat_id, c.code, c.code,
       CASE WHEN d.chk IS NULL THEN 'Valid' ELSE 'CheckedIn' END,
       CASE WHEN d.chk IS NULL THEN NULL ELSE DATEADD(MINUTE, d.chk + (es.seat_number % 4), @now) END,
       DATEADD(MINUTE, d.c_off + 4, @now)
FROM #OSR s
JOIN #ORD d ON d.code = s.code
JOIN Orders o ON o.order_code = s.code
JOIN #EVID i ON i.k = d.k
JOIN #TKID ti ON ti.k = d.k AND ti.tidx = s.tidx
JOIN Order_Details od ON od.order_id = o.order_id AND od.event_ticket_id = ti.event_ticket_id
JOIN Event_Seats es ON es.event_id = i.event_id AND es.row_label = s.row_label
                   AND es.seat_number BETWEEN s.from_no AND s.from_no + s.cnt - 1
CROSS APPLY (SELECT 'TKT-' + CONVERT(VARCHAR(32), HASHBYTES('MD5', d.code + ':S:' + CAST(es.event_seat_id AS VARCHAR(12))), 2) AS code) c
WHERE d.st = 'Paid'
ORDER BY o.order_id, es.event_seat_id;

-- 3 vé lẻ đã hủy/hoàn tiền (đơn vẫn Paid) để test trạng thái Cancelled khi check-in
UPDATE t SET t.ticket_status = 'Cancelled', t.check_in_time = NULL
FROM Tickets t
JOIN Event_Seats es ON es.event_seat_id = t.event_seat_id
JOIN Order_Details od ON od.order_detail_id = t.order_detail_id
JOIN Orders o ON o.order_id = od.order_id
JOIN #CT c ON c.code = o.order_code AND c.row_label = es.row_label AND c.seat_no = es.seat_number;

-- Trạng thái ghế: Sold (đơn Paid), Held (đơn Pending đang giữ chỗ), vé đã hủy thì ghế trống lại
UPDATE es SET es.status = 'Sold'
FROM Event_Seats es
JOIN Order_Seats os ON os.event_seat_id = es.event_seat_id
JOIN Orders o ON o.order_id = os.order_id
WHERE o.status = 'Paid';

UPDATE es SET es.status = 'Available'
FROM Event_Seats es
JOIN Tickets t ON t.event_seat_id = es.event_seat_id
JOIN #EVID i ON i.event_id = t.event_id
WHERE t.ticket_status = 'Cancelled';

UPDATE es SET es.status = 'Held'
FROM Event_Seats es
JOIN Order_Seats os ON os.event_seat_id = es.event_seat_id
JOIN Orders o ON o.order_id = os.order_id
WHERE o.status = 'Pending';

-- Số vé còn lại = sức chứa - vé trong đơn Paid/Pending + vé đã hủy lẻ
UPDATE et SET et.available_quantity = et.quantity - ISNULL(s.q, 0) + ISNULL(c.n, 0)
FROM Event_Tickets et
JOIN #TKID ti ON ti.event_ticket_id = et.event_ticket_id
LEFT JOIN (SELECT od.event_ticket_id, SUM(od.quantity) AS q
           FROM Order_Details od JOIN Orders o ON o.order_id = od.order_id
           WHERE o.status IN ('Paid', 'Pending') GROUP BY od.event_ticket_id) s ON s.event_ticket_id = et.event_ticket_id
LEFT JOIN (SELECT od.event_ticket_id, COUNT(*) AS n
           FROM Tickets t JOIN Order_Details od ON od.order_detail_id = t.order_detail_id
           WHERE t.ticket_status = 'Cancelled' GROUP BY od.event_ticket_id) c ON c.event_ticket_id = et.event_ticket_id;

-- Lượt dùng voucher = số đơn Paid/Pending đang dùng voucher đó
UPDATE vc SET vc.used_count = (SELECT COUNT(*) FROM Orders o WHERE o.voucher_id = vc.voucher_id AND o.status IN ('Paid', 'Pending'))
FROM Vouchers vc
WHERE vc.voucher_code IN ('FLASH20', 'WELCOME30K', 'VIPDEAL100', 'SUMMER15', 'LIMITED10', 'TET2027', 'BLACKFRI');
GO

