INSERT INTO Reviews (customer_id, event_id, ticket_id, rating, comment, status, created_at, updated_at)
SELECT u.user_id, i.event_id, x.ticket_id, r.rating, r.comment, r.st, DATEADD(MINUTE, r.c_off, @now), DATEADD(MINUTE, r.c_off, @now)
FROM #RV r
JOIN Users u ON u.username = 'customer' + RIGHT('0' + CAST(r.cust AS VARCHAR(2)), 2)
JOIN #EVID i ON i.k = r.k
CROSS APPLY (SELECT TOP 1 t.ticket_id
             FROM Tickets t
             JOIN Order_Details od ON od.order_detail_id = t.order_detail_id
             JOIN Orders o ON o.order_id = od.order_id
             WHERE o.customer_id = u.user_id AND t.event_id = i.event_id AND t.ticket_status = 'CheckedIn'
             ORDER BY t.ticket_id) x
ORDER BY r.c_off;

DROP TABLE #RV, #CT, #RF, #OSR, #ORD, #ES, #TKID, #TK, #ZN, #EVID, #EV, #N;
GO

