/*
  007: Bỏ 2 sự kiện demo cũ, thêm 40 sự kiện mới (kèm poster riêng) và lịch staff01 từ 12/11 đến 17/11/2026.
  Chạy sau db.sql (hoặc trên DB đang dùng): sqlcmd -S localhost -U sa -P 123 -C -d LightTicketDB -f 65001 -i db\migrations\007_more_events_and_staff_schedule.sql
*/
SET NOCOUNT ON;
SET XACT_ABORT ON;
-- sqlcmd mặc định tắt QUOTED_IDENTIFIER, nhưng bảng có filtered index yêu cầu bật khi ghi dữ liệu
SET QUOTED_IDENTIFIER ON;
GO

-- ---------------------------------------------------------------- Bỏ 2 sự kiện demo cũ
-- Xóa luôn đơn hàng / vé / đánh giá / ghế / hạng vé / phân công gắn với 2 sự kiện này (đúng thứ tự khóa ngoại).
BEGIN TRANSACTION;
DECLARE @old TABLE (event_id INT PRIMARY KEY);
INSERT INTO @old SELECT event_id FROM Events
WHERE event_name IN (N'Chuyến Bay Hoàng Hôn: Live Concert 2026', N'Vở Kịch Kinh Điển: Người Tình Mùa Thu');

DECLARE @oldOrders TABLE (order_id INT PRIMARY KEY);
INSERT INTO @oldOrders
SELECT DISTINCT od.order_id FROM Order_Details od
JOIN Event_Tickets et ON et.event_ticket_id = od.event_ticket_id
WHERE et.event_id IN (SELECT event_id FROM @old);

DELETE FROM Reviews WHERE event_id IN (SELECT event_id FROM @old);
DELETE FROM Tickets WHERE event_id IN (SELECT event_id FROM @old);
DELETE FROM Payments WHERE order_id IN (SELECT order_id FROM @oldOrders);
DELETE FROM Order_Seats WHERE order_id IN (SELECT order_id FROM @oldOrders)
   OR event_seat_id IN (SELECT event_seat_id FROM Event_Seats WHERE event_id IN (SELECT event_id FROM @old));
DELETE FROM Order_Details WHERE order_id IN (SELECT order_id FROM @oldOrders);
DELETE FROM Orders WHERE order_id IN (SELECT order_id FROM @oldOrders);
DELETE FROM Event_Seats WHERE event_id IN (SELECT event_id FROM @old);
DELETE FROM Event_Zones WHERE event_id IN (SELECT event_id FROM @old);
DELETE FROM Event_Tickets WHERE event_id IN (SELECT event_id FROM @old);
DELETE FROM Event_Staff WHERE event_id IN (SELECT event_id FROM @old);
DELETE FROM Events WHERE event_id IN (SELECT event_id FROM @old);
COMMIT TRANSACTION;
PRINT N'Đã bỏ 2 sự kiện demo cũ (nếu có).';
GO

