-- ---------------------------------------------------------------- 40 sự kiện mới (ACTIVE, organizer01)
-- Poster nằm ở src/main/webapp/assets/images/events/<slug>.svg, mỗi sự kiện một ảnh riêng.
-- 13 sự kiện từ 12/11 đến 17/11/2026 được phân công cho staff01 (mỗi ngày đều có ít nhất 1 sự kiện).
-- Chạy lại nhiều lần an toàn: sự kiện trùng tên đã có hạng vé thì bỏ qua.
BEGIN TRANSACTION;
DECLARE @organizerId INT = (SELECT user_id FROM Users WHERE username = 'organizer01');
DECLARE @staffId INT = (SELECT user_id FROM Users WHERE username = 'staff01');
IF @organizerId IS NULL
BEGIN
    RAISERROR(N'Thiếu organizer01. Hãy chạy db.sql trước.', 16, 1);
    ROLLBACK TRANSACTION;
    RETURN;
END

