-- Bảng số 0..39 để sinh hàng / cột ghế
DECLARE @N TABLE (n INT PRIMARY KEY);
INSERT INTO @N SELECT TOP 40 ROW_NUMBER() OVER (ORDER BY (SELECT NULL)) - 1 FROM sys.all_objects;

DECLARE @k INT = 1, @eventId INT, @name NVARCHAR(200);
WHILE @k <= 40
BEGIN
    SELECT @name = event_name FROM @E WHERE k = @k;
    SET @eventId = (SELECT TOP 1 event_id FROM Events WHERE event_name = @name ORDER BY event_id);

    IF @eventId IS NULL
    BEGIN
        INSERT INTO Events (organizer_id, category_id, venue_id, event_name, description, event_image, start_time, end_time, status)
        SELECT @organizerId,
               (SELECT TOP 1 category_id FROM Categories WHERE category_name = e.category_name ORDER BY category_id),
               (SELECT TOP 1 venue_id FROM Venues WHERE venue_name = e.venue_name ORDER BY venue_id),
               e.event_name, e.description, e.image, e.start_time, e.end_time, 'ACTIVE'
        FROM @E e WHERE e.k = @k;
        SET @eventId = SCOPE_IDENTITY();
    END

    IF NOT EXISTS (SELECT 1 FROM Event_Tickets WHERE event_id = @eventId)
    BEGIN
        -- Hạng vé: số lượng = tổng sức chứa các khu gắn với hạng vé đó
        INSERT INTO Event_Tickets (event_id, ticket_name, description, price, quantity, available_quantity, status)
        SELECT @eventId, t.ticket_name, t.description, t.price, cap.qty, cap.qty, 'ACTIVE'
        FROM @T t
        CROSS APPLY (SELECT SUM(CASE WHEN z.zone_type = 'SEATED' THEN z.row_count * z.seats_per_row
                                     ELSE z.standing_capacity END) AS qty
                     FROM @Z z WHERE z.ek = @k AND z.ticket_name = t.ticket_name) cap
        WHERE t.ek = @k;

        DELETE FROM Event_Seats WHERE event_id = @eventId;
        DELETE FROM Event_Zones WHERE event_id = @eventId;
        INSERT INTO Event_Zones (event_id, event_ticket_id, zone_name, zone_type, color, pos_x, pos_y, width, height,
                                 row_count, seats_per_row, capacity, blocked_seats, sort_order)
        SELECT @eventId, et.event_ticket_id, z.zone_name, z.zone_type, z.color, z.pos_x, z.pos_y, z.width, z.height,
               z.row_count, z.seats_per_row,
               CASE z.zone_type WHEN 'SEATED' THEN z.row_count * z.seats_per_row
                                WHEN 'STANDING' THEN z.standing_capacity ELSE 0 END,
               NULL, z.sort_order
        FROM @Z z
        LEFT JOIN Event_Tickets et ON et.event_id = @eventId AND et.ticket_name = z.ticket_name
        WHERE z.ek = @k;

        -- Ghế cho khu ngồi (giống trình thiết kế sơ đồ của Organizer)
        INSERT INTO Event_Seats (event_id, source_seat_id, zone_id, row_label, seat_number, seat_label, seat_type, status)
        SELECT @eventId, NULL, ez.zone_id,
               z.code + '-' + CHAR(65 + r.n),
               c.n + 1,
               z.code + '-' + CHAR(65 + r.n) + RIGHT('0' + CAST(c.n + 1 AS VARCHAR(2)), 2),
               CASE WHEN LOWER(z.zone_name) LIKE '%vip%' THEN 'VIP' ELSE 'Standard' END,
               'Available'
        FROM @Z z
        JOIN Event_Zones ez ON ez.event_id = @eventId AND ez.zone_name = z.zone_name
        JOIN @N r ON r.n < z.row_count
        JOIN @N c ON c.n < z.seats_per_row
        WHERE z.ek = @k AND z.zone_type = 'SEATED'
        ORDER BY ez.sort_order, r.n, c.n;

        PRINT N'Đã tạo: ' + @name;
    END
    ELSE
        PRINT N'Bỏ qua (đã có hạng vé): ' + @name;

    SET @k += 1;
END

-- Phân công staff01 cho các sự kiện 12/11 - 17/11/2026 (bỏ qua nếu đã phân công)
IF @staffId IS NOT NULL
    INSERT INTO Event_Staff (event_id, staff_id, status)
    SELECT ev.event_id, @staffId, 'ACTIVE'
    FROM @E e
    CROSS APPLY (SELECT TOP 1 event_id FROM Events WHERE event_name = e.event_name ORDER BY event_id) ev
    WHERE e.for_staff = 1
      AND NOT EXISTS (SELECT 1 FROM Event_Staff s WHERE s.event_id = ev.event_id AND s.staff_id = @staffId);

-- Ảnh poster: chỉ ghi khi chưa có ảnh hoặc ảnh cũ không phải ảnh Organizer tự upload
UPDATE ev SET event_image = e.image, updated_at = GETDATE()
FROM Events ev JOIN @E e ON e.event_name = ev.event_name
WHERE ev.event_image IS NULL OR ev.event_image NOT LIKE 'assets/uploads/%';

COMMIT TRANSACTION;
GO

-- ==============================================================================
-- MERGED SECTION 4/4: fix_missing_event_posters.sql
-- Fill missing event_image paths without overwriting existing event posters.
-- ==============================================================================

-- Light Ticket: gan poster minh hoa cho cac su kien chua co anh
-- Khong xoa database, khong ghi de poster da co.
USE LightTicketDB;
GO

UPDATE ev
SET ev.event_image = CASE c.category_name
    WHEN N'Concert Âm Nhạc' THEN 'assets/images/events/chuyen-bay-hoang-hon.svg'
    WHEN N'Gia đình & Thiếu nhi' THEN 'assets/images/events/ltm-thieu-nhi.svg'
    WHEN N'Hài kịch & Stand-up' THEN 'assets/images/events/ltm-hai-kich.svg'
    WHEN N'Hội thảo & Workshop' THEN 'assets/images/events/ltm-hoi-thao.svg'
    WHEN N'Lễ hội & Ẩm thực' THEN 'assets/images/events/ltm-le-hoi.svg'
    WHEN N'Sân Khấu & Kịch' THEN 'assets/images/events/hon-truong-ba.svg'
    WHEN N'Thể thao' THEN 'assets/images/events/ltm-the-thao.svg'
    WHEN N'Triển lãm & Nghệ thuật' THEN 'assets/images/events/ltm-trien-lam.svg'
    ELSE 'assets/images/events/ltm-le-hoi.svg'
END
FROM Events ev
LEFT JOIN Categories c ON c.category_id = ev.category_id
WHERE ev.event_image IS NULL OR LTRIM(RTRIM(ev.event_image)) = '';

SELECT event_id, event_name, event_image
FROM Events
WHERE event_image IS NULL OR LTRIM(RTRIM(event_image)) = '';
GO
